export type NodeParams_jd_math_remap_1 = {
  /** Input range mapped from. */
  "from"?: [number, number];
  /** Output range mapped to. */
  "to"?: [number, number];
  /** Clamp to the output range. */
  "clamp"?: boolean;
};

export type NodeParams_jd_math_scale_1 = {
  /** Multiplier. */
  "factor"?: number;
};

export type NodeParams_jd_noise_fbm_1 = {
  /** Lattice. */
  "kind"?: NoiseKind;
  /** Fractal combinator. */
  "fractal"?: FractalKind;
  /** Seed (combined with the world seed by the caller when desired). */
  "seed"?: number;
  /** Feature size in metres (wavelength of the first octave). */
  "feature_size_m"?: number;
  /** Octave count (1–16). */
  "octaves"?: number;
  /** Frequency multiplier per octave. */
  "lacunarity"?: number;
  /** Amplitude multiplier per octave. */
  "gain"?: number;
  /** Output height range in metres: noise ∈ [-1,1] maps to [min, max]. */
  "height_range_m"?: [number, number];
  /** Offset of the sampling origin in metres. */
  "offset_m"?: [number, number];
};

export type NodeParams_jd_ocean_bathymetry_1 = {
  /** Sea level, metres: sediment never builds above it. */
  "level_m"?: number;
  /** Smoothing reach, metres (> 0): hollows narrower than this fill in. */
  "smooth_m"?: number;
  /** Thickest sediment layer laid down anywhere, metres (≥ 0). */
  "max_fill_m"?: number;
  /** How much of the infill to apply, 0..1 (1 = level the hollow completely). */
  "strength"?: number;
};

export type NodeParams_jd_output_height_1 = {
  /** Layer name the result is published under. */
  "layer"?: string;
};

export type StrokeMode = "raise" | "smooth" | "flatten";

export type Stroke = {
  /** Polyline in layer metres: `[u east, v north]` from the south-west corner (row 0 = south). */
  "points": ([number, number])[];
  /** Brush radius in metres. */
  "radius_m": number;
  /** Height added at the centre for `raise` (negative lowers), metres. */
  "strength_m"?: number;
  /** Brush behaviour (default `raise`). */
  "mode"?: StrokeMode;
  /** Blend factor 0..1 for `smooth` / `flatten` (default 0.5). */
  "amount"?: number;
};

export type NodeParams_jd_sculpt_strokes_1 = {
  /** Recorded brush strokes, applied in order on top of the input. */
  "strokes"?: Stroke[];
};

export type NodeParams_jd_terrain_strata_1 = {
  /** Thickness of one hard+soft cycle, metres (> 0). */
  "layer_m"?: number;
  /** Share of each cycle that is hard caprock, 0..1 (the rest is soft). */
  "hard_fraction"?: number;
  /** Hardness of the cap, 0..1 (1 = holds vertical cliffs, erodes at a tenth of the rate). */
  "hard"?: number;
  /** Hardness of the soft bed, 0..1. */
  "soft"?: number;
  /** Width of the hard↔soft transition as a fraction of the cycle, 0..0.5. */
  "transition"?: number;
  /** Dip of the beds, degrees from horizontal, [0, 60]. */
  "dip_deg"?: number;
  /** Direction the beds dip towards, degrees clockwise from north. */
  "dip_azimuth_deg"?: number;
  /** Undulation of the bed surfaces, metres (≥ 0): 0 for flat beds. */
  "warp_m"?: number;
  /** Undulation seed. */
  "seed"?: number;
};

/** Request and result types of every core operation, keyed by op id. */
export interface JdOps {
  /** Run a benchmark scene (S1: fBm + ridged + add + thermal×50) with the real kernels; per-stage wall time, peak RSS, content hash */
  "diag.bench": { request: DiagBenchRequest; result: DiagBenchResult };
  /** Report host environment and detected tools */
  "diag.env": { request: DiagEnvRequest; result: DiagEnvResult };
  /** Add a node (journaled) */
  "graph.add_node": { request: GraphAddNodeRequest; result: GraphAddNodeResult };
  /** Push one element onto an array parameter (brush strokes): journaled with just the element, so a long sculpt session grows the journal linearly */
  "graph.append_param": { request: GraphAppendParamRequest; result: GraphAppendParamResult };
  /** Connect an output to an input (journaled; rejects bad ports, type mismatches and cycles) */
  "graph.connect": { request: GraphConnectRequest; result: GraphConnectResult };
  /** Remove an edge (journaled) */
  "graph.disconnect": { request: GraphDisconnectRequest; result: GraphDisconnectResult };
  /** Validate and evaluate the graph incrementally; publishes output nodes as layers (`<layer>#lod<N>` when lod > 0) */
  "graph.evaluate": { request: GraphEvaluateRequest; result: GraphEvaluateResult };
  /** Start graph.evaluate on a worker thread and return at once with `status: accepted` + `job_id`; follow it with jobs.list, cancel with jobs.cancel, collect the envelope with jobs.result */
  "graph.evaluate_async": { request: GraphEvaluateAsyncRequest; result: GraphEvaluateAsyncResult };
  /** List available node kinds with ports and parameter schemas */
  "graph.kinds": { request: GraphKindsRequest; result: GraphKindsResult };
  /** Nodes and edges of the open project's graph */
  "graph.list": { request: GraphListRequest; result: GraphListResult };
  /** Move a node on the editor canvas (journaled) */
  "graph.move_node": { request: GraphMoveNodeRequest; result: GraphMoveNodeResult };
  /** Re-apply the last undone graph edit (journaled as graph.restore) */
  "graph.redo": { request: GraphRedoRequest; result: GraphRedoResult };
  /** Remove a node and its edges (journaled) */
  "graph.remove_node": { request: GraphRemoveNodeRequest; result: GraphRemoveNodeResult };
  /** Bypass or un-bypass a node (journaled) */
  "graph.set_bypass": { request: GraphSetBypassRequest; result: GraphSetBypassResult };
  /** Set (or null to reset) a node parameter (journaled; validated against the kind's schema) */
  "graph.set_param": { request: GraphSetParamRequest; result: GraphSetParamResult };
  /** Move the timeline (0..1, journaled): parameters written as `{"keys": [[t, v], …]}` interpolate here — numbers linearly, anything else stepwise — so erosion steps, sea level or wind can be scrubbed and keyframed */
  "graph.set_time": { request: GraphSetTimeRequest; result: GraphSetTimeResult };
  /** Take back the last graph edit (journaled as graph.restore) */
  "graph.undo": { request: GraphUndoRequest; result: GraphUndoResult };
  /** Request cancellation of a running job; it stops at the next node or kernel iteration with E_CANCELLED */
  "jobs.cancel": { request: JobsCancelRequest; result: JobsCancelResult };
  /** Running jobs with progress (steps done/total, current node) — poll while an evaluation runs */
  "jobs.list": { request: JobsListRequest; result: JobsListResult };
  /** State of a job: running (progress), done (the finished op's envelope, handed over once) or unknown */
  "jobs.result": { request: JobsResultRequest; result: JobsResultResult };
  /** Write the water textures of a sea at `level_m`: depth (16-bit), the water's colour through its clarity and tint (sRGB), the shoreline + surf foam, and a tileable Gerstner wave normal map for the wind sea */
  "ocean.bake": { request: OceanBakeRequest; result: OceanBakeResult };
  /** Wind sea for a wind speed and fetch (JONSWAP growth capped at the fully developed Pierson–Moskowitz sea): significant height, peak period and wavelength, breaking depth, and the Gerstner components the viewport animates */
  "ocean.waves": { request: OceanWavesRequest; result: OceanWavesResult };
  /** Evict the oldest cached layer blobs until the project's cache fits `settings.cache_limit_bytes` (the cache is disposable); reports what is left */
  "project.cache_gc": { request: ProjectCacheGcRequest; result: ProjectCacheGcResult };
  /** Close the open project (unsaved changes stay in the journal) */
  "project.close": { request: ProjectCloseRequest; result: ProjectCloseResult };
  /** Create a new project directory and open it */
  "project.create": { request: ProjectCreateRequest; result: ProjectCreateResult };
  /** Copy a file (DEM, heightmap, texture) into the project's assets/ so nodes can reference it by name */
  "project.import_asset": { request: ProjectImportAssetRequest; result: ProjectImportAssetResult };
  /** Describe the open project */
  "project.info": { request: ProjectInfoRequest; result: ProjectInfoResult };
  /** Open an existing project */
  "project.open": { request: ProjectOpenRequest; result: ProjectOpenResult };
  /** Replay unsaved journal entries found when the project was opened, then save (entries that fail stay pending unless discard_failed) */
  "project.recover": { request: ProjectRecoverRequest; result: ProjectRecoverResult };
  /** Write the open project to disk */
  "project.save": { request: ProjectSaveRequest; result: ProjectSaveResult };
  /** Rename the open project */
  "project.set_name": { request: ProjectSetNameRequest; result: ProjectSetNameResult };
  /** Change project settings (autosave interval, cache limit, preview LOD); fields left out keep their value — journaled like every mutation */
  "project.set_settings": { request: ProjectSetSettingsRequest; result: ProjectSetSettingsResult };
  /** Bake a physical sky (Preetham daylight model: sun azimuth/elevation, turbidity) as an equirectangular HDRI — OpenEXR RGB f32 for engines and renderers, with a tonemapped PNG preview beside it */
  "sky.bake": { request: SkyBakeRequest; result: SkyBakeResult };
  /** Write a layer as EXR (f32), PNG16, RAW r16 or r32 with a JSON sidecar */
  "terrain.export_heightmap": { request: TerrainExportHeightmapRequest; result: TerrainExportHeightmapResult };
  /** Write a layer as a grid mesh — .glb (normals, UVs, PBR material with baked base-colour texture), .fbx (binary 7.4 quads, Phong material with the baked texture embedded), .obj, binary .stl, binary .ply with vertex colours, .usda, or .usdz (needs usdzip) — metres, +Y up, centred on the world */
  "terrain.export_mesh": { request: TerrainExportMeshRequest; result: TerrainExportMeshResult };
  /** Write a Unity or Unreal terrain import set: heightmap in the engine's encoding and row order, one 8-bit weightmap per mask layer, and a README with the computed Terrain Height / Z scale */
  "terrain.export_profile": { request: TerrainExportProfileRequest; result: TerrainExportProfileResult };
  /** Generate a noise heightfield for the open project's world and store it as a layer */
  "terrain.generate": { request: TerrainGenerateRequest; result: TerrainGenerateResult };
  /** Downsampled u16 preview of a layer (base64) for agents and viewers */
  "terrain.preview": { request: TerrainPreviewRequest; result: TerrainPreviewResult };
  /** Scatter instance points over the world from a 0..1 density mask layer (stratified jittered grid, deterministic by seed): write CSV / JSON / GLB instances to `path`, or return the points when `path` is omitted */
  "terrain.scatter": { request: TerrainScatterRequest; result: TerrainScatterResult };
  /** Statistics and content hash of a layer */
  "terrain.stats": { request: TerrainStatsRequest; result: TerrainStatsResult };
  /** Bake the material maps of a layer — albedo, tangent-space normal, roughness — as PNGs (base64) for viewers and engines */
  "terrain.textures": { request: TerrainTexturesRequest; result: TerrainTexturesResult };
}

export type OpId = keyof JdOps;

